import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Data Scaling Laws in Imitation Learning for Robotic Manipulation","description":"","frontmatter":{"title":"Data Scaling Laws in Imitation Learning for Robotic Manipulation","arxiv":"2410.18647","date":"2024-10-24","authors":"Fanqi Lin, Yingdong Hu, Pingyue Sheng, Chuan Wen, Jiacheng You, Yang Gao","categories":"cs.RO","topics":"通用具身智能, 模仿学习, 数据规模律","outline":[2,2]},"headers":[],"relativePath":"papers/2410.18647.md","filePath":"papers/2410.18647.md","lastUpdated":null}'),l={name:"papers/2410.18647.md"};function e(r,s,i,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="data-scaling-laws-in-imitation-learning-for-robotic-manipulation" tabindex="-1">Data Scaling Laws in Imitation Learning for Robotic Manipulation <a class="header-anchor" href="#data-scaling-laws-in-imitation-learning-for-robotic-manipulation" aria-label="Permalink to &quot;Data Scaling Laws in Imitation Learning for Robotic Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2410.18647" target="_blank" rel="noreferrer">2410.18647</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-10-24</td></tr><tr><td><strong>作者</strong></td><td>Fanqi Lin, Yingdong Hu, Pingyue Sheng, Chuan Wen, Jiacheng You, Yang Gao</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用手持夹爪在 32 个环境 × 32 个物体上做受控数据扫描，发现单任务策略的泛化缺口随环境数、物体数呈幂律下降，而每个环境的演示条数很快饱和。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 arXiv <strong>v4</strong>（2026-06-26 修订）的 HTML 全文撰写，v1 提交于 2024-10-24。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人操作的数据在涨，但没人知道该往哪个方向涨。语言模型有 Kaplan 式的 scaling law 把「加数据 → 降 loss」量化成可外推的曲线，机器人没有对应物：OXE 汇集了 22 种本体、超过 100 万条轨迹，可部署到新场景时仍然要重新采数据微调。于是从业者只能凭直觉在三个轴上分配预算——采多少个环境、多少个物体、每个组合采多少条演示。</p><p>本文把这个预算分配问题当作一等公民来测：固定任务、固定算法（Diffusion Policy），只改数据的构成，问单任务策略在<strong>没见过的环境</strong>和<strong>没见过的同类物体</strong>上的表现如何随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span>（环境数）、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>（物体数）、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span>（每组合演示数）变化。价值很直接：如果泛化缺口对多样性是幂律、对演示条数是饱和的，那么「一个下午采完、直接零样本部署」就从口号变成可计算的采集方案。作者最终交付的正是这样一条配方，并用两个全新任务做了验证。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>UMI 已经证明多样化演示能显著提升策略在新环境新物体上的表现，RUMs（与本文同期）也做出了可零样本部署的策略，但两者都停在「更多样更好」这一步，没有把泛化能力与各个数据维度的关系拆开量化。OXE 这类大规模汇集工作的目标是跨本体正迁移，评测口径是微调后的性能，因此无法回答「不微调能不能用」。</p><p>泛化性评测这一侧的做法也有结构性缺陷。此前的研究习惯把变化因子逐个隔离：用特制灯光只改照明色温，用 3D 打印件只改尺寸不改几何。这种设计能给出干净的因果归因，代价是它既穷举不完真实世界的因子，也回避了真实部署时多个因子同时变动的情形。本文的选择是放弃因子级隔离，直接把「环境」和「物体」当成两个复合维度，靠在真实场景里铺开采集来覆盖联合分布。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个已知事实：NLP 的 scaling law 建立在「数据量」这个一维标量上，而机器人数据没有天然的一维标量——1000 条同一场景同一物体的演示和 1000 条散布在 32 个场景的演示完全不是一回事。要写出 scaling law，第一步必须把「数据量」分解成语义上正交的坐标，环境与物体是最贴近部署失败模式的两个。</p><p>第二步是可行性。要在 32 个真实场景里各采上百条演示，遥操作机械臂的搬运成本不可接受；UMI 这类手持夹爪把采集成本压到「换个场景就能继续采」的量级，代价是依赖 SLAM，纹理稀疏的场景会丢数据（本文实测约 90% 的演示有效）。</p><p>第三步是度量。成功率是稀疏信号，在策略明显进步但仍失败时完全不动，无法支撑幂律拟合；验证集上的动作 MSE 又与真机表现常常脱节。于是作者设计了分步打分：每个任务拆成 2–3 步、每步最多 3 分，归一化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，并让多个策略在同一初始条件下交错 rollout 以压住打分者的主观偏置。这三步做完，剩下的就是把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7477em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span> 的网格跑满。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>策略在新环境里失败，不是因为它见过的演示太少，而是因为它见过的<strong>世界</strong>太少。一旦某个环境里已经有几十条演示把动作模式讲清楚，再加同一环境的演示只是在重复同一份关于「世界长什么样」的证据；换一个环境采同样多的演示，则是给视觉编码器提供了一个全新的不变性约束。因此多样性维度上是幂律式的持续收益，演示条数维度上是快速饱和。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Pour Water 为例（抓起桌上随机摆放的水瓶、把水倒进杯子、把瓶子放回红色杯垫，三步计分）：</p><ul><li><strong>输入</strong>：操作者手持 UMI 夹爪，在一个真实场景（客厅茶几、办公室工位、咖啡馆桌面……）中对一个具体的瓶子演示若干次，录下腕部相机视频与 SLAM 推出的末端位姿。</li><li><strong>数据构造</strong>：跑 SLAM 过滤，得到有效演示；按实验设计随机抽取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span></span></span></span></span></span></span></span> 个环境（或物体、或环境-物体配对）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span> 比例的演示，只有总量超过 100 条才训练。</li><li><strong>策略</strong>：Diffusion Policy，噪声预测网络是 CNN-based 1D U-Net，推理用 DDIM 保证实时；视觉编码器换成<strong>全量微调</strong>的 DINOv2 ViT-L/14；执行时加 ACT 式 temporal ensemble，用指数加权平均重叠的动作序列，消除切换时的抖动。</li><li><strong>评测</strong>：只在训练未见的 8 个环境（或 8 个物体）上测，每个 5 次试验，报 40 次的平均归一化分。</li><li><strong>输出</strong>：一条 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">m</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">n</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">↦</span></span></span></span> 分数的曲面，以及在 log-log 坐标上对其做的直线拟合。</li></ul><p>最终配方：<strong>在尽可能多的不同环境里各放一个不同物体、每个组合采 50 条演示，凑够 32 个环境-物体配对</strong>。四名采集者用一个下午就能为一个新任务采完这个量。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>幂律的形式是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0037em;">α</span></span></span></span></span></span></span></span></span></span></span></span>，两边取对数得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>，于是在 log-log 图上是一条斜率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 的直线，用 Pearson 相关系数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 判断拟合优劣。</p><p>关键在于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span></span></span></span> 取什么。作者取的是 <strong>optimality gap</strong>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Normalized Score</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">Normalized Score</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord cjk_fallback">步骤数</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">总得分</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>即「离满分还差多少」，这与语言模型里用交叉熵 loss 而非准确率作纵轴是同一个动机——只有误差量才可能跨数量级线性下降。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span> 则分别取环境数、物体数、环境-物体配对数。</p><p>这里有一个作者自己点明的取舍。更完整的模型应是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0037em;">α</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∞</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∞</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是仅靠堆数据消不掉的不可约误差（传感器噪声、UMI 的标定误差、任务本身的不可完成实例）。作者明确写道：每条曲线只有 6 个数据点，拟合三参数模型在统计上站不住，因此只用两参数形式。这一步等价于<strong>假设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∞</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span></strong>，即数据足够多时分数可以趋近 1。基于该拟合，作者外推出 Mouse Arrangement 要在新环境新物体上拿到 0.99 分需要约 1191 个环境-物体配对，并声明该预测留待验证。</p><p>演示条数这一维不满足幂律：在最大数据设定下拟合出的相关系数只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.62</span></span></span></span>（Pour Water）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.79</span></span></span></span>（Mouse Arrangement），曲线在 800 条附近走平。附录里对动作 MSE 也做了同样的拟合，幂律大体成立但所有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord">∣</span></span></span></span> 都更小，个别情形低到 0.558。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>物体维度能涨到什么程度？</strong> 单一环境、32 个物体、每物体 120 条演示。结论是物体泛化便宜得出乎意料：8 个物体就让两个任务的归一化分越过 0.8，32 个物体越过 0.9；而且物体越多，每个物体需要的演示越少——8 个物体时用 12.5% 演示明显落后于全量，32 个物体时这个差距几乎消失。</p><p><strong>环境维度呢？</strong> 同一物体、32 个环境。趋势一致但斜率更平：在数量少时，加环境带来的收益小于加物体，说明环境泛化更难。同时 50% 与 100% 演示的两条曲线几乎重合，即演示的边际收益迅速归零。</p><p><strong>两个维度同时变呢？</strong> 32 个环境各配一个独立物体。更难的设定反而让演示饱和得更快（25% 与 100% 的曲线重合），因为同时改变两者本身就提高了数据多样性。</p><p><strong>一个环境里多放几个物体划算吗？</strong> 16 个环境 × 4 个物体的热力图显示：环境数少时有用，环境数到 16 时「每个环境 4 个物体」与「每个环境 1 个物体」几乎没有差别。因此推荐一环境一物体。</p><p><strong>演示条数的阈值在哪？</strong> 8、16、32 个配对分别在 400、800、1600 条总演示处走平，折合每配对 50 条。</p><p><strong>配方能迁移吗？</strong> 用该配方为 Fold Towels 与 Unplug Charger 各采 32 配对 × 50 条，8 个未见环境 × 2 个未见物体 × 5 次试验，四个任务的成功率分别是 85.0±19.4%、92.5±9.7%、87.5±17.1%、90.0±14.1%。</p><p><strong>模型侧呢？</strong> 在 Pour Water 上，视觉编码器从零训练得 0.03、冻结 DINOv2 得 0.00、LoRA（rank=8）得 0.72、全量微调得 0.90；编码器规模 ViT-S/B/L 依次 0.66 / 0.81 / 0.90；而动作扩散 U-Net 从 small 到 large 是 0.88 / 0.90 / 0.83，放大反而略降。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：机器人模仿学习的数据规模律要按「环境数、物体数、每组合演示数」三个轴分别写，不能合并成一个标量。前两个轴上，泛化缺口 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord text"><span class="mord">score</span></span></span></span></span> 随数量呈幂律下降；第三个轴上性能很快饱和，每组合约 50 条即可。凑够 32 个「一环境一物体」的配对，就足以训练出在全新环境、全新同类物体上约 90% 成功率的单任务策略，采集成本是四个人一个下午。视觉编码器必须预训练且全量微调，且放大编码器有效；放大动作扩散网络无效。所有结论建立在 4 个任务、超过 4 万条演示与 1.5 万次真机 rollout 上。</p><p><strong>3 句话版</strong>：多样性远比演示数量重要，且它的收益服从幂律。32 个环境-物体配对 × 50 条演示是一个可复现的「够用」阈值。瓶颈在视觉编码器而不在动作头。</p><p><strong>1 句话版</strong>：别在同一个房间里采第 100 条演示，去下一个房间采第 1 条。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最贵的假设是 <strong><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span></strong>——幂律外推时默认不存在不可约误差。全文最有实践价值的两个结论都建立在它之上：一是「32 个配对够用」这个阈值本质上是在拟合曲线上读点，二是「1191 个配对可达 0.99」这个预测完全是外推。</p><p>它在实践中很可能不成立。UMI 依赖 SLAM，作者自己报告约 10% 的演示因纹理不足被丢弃，而被丢弃的场景恰恰是系统性偏难的那一类；末端位姿本身带标定误差，这会给动作标签注入与数据量无关的噪声底；四个任务里表现最差的 Unplug Charger（0.887 ± 0.14）是最依赖接触力而非视觉的那个。这些都指向一个正的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</p><p>论文为此提供的证据是间接的：6 个点的 log-log 拟合确实很直，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 接近 1。但两参数模型在只有 6 个点、且横轴只跨 5 个倍频程时，几乎无法与「带小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的三参数模型」区分开——作者自己也是因为点太少才拒绝拟合三参数版本。真正缺的证据是把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span> 再推大一个数量级后的实测点，而这恰恰是论文明确留给未来工作的部分。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做且不需要重采数据的版本：</p><ol><li>取一个已有的多场景数据集（如 DROID 或 Bridge V2 的某个单任务子集），按采集场景 ID 分组，构造 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span></span></span></span></span></span></span></span> 个场景的子集（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0..4</span></span></span></span>），每场景固定条数。</li><li>用同一套 Diffusion Policy 训练，评测在留出场景上的动作 MSE（本文附录 G.1 证明 MSE 上也大体成立幂律，虽然更弱）。</li><li>在 log-log 坐标上拟合两参数模型，同时拟合带 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的三参数模型，比较 AIC/BIC。</li><li><strong>判据</strong>：若两参数模型在留出的最大规模点上系统性高估性能，而三参数模型不高估，则本文的外推结论（1191 配对达 0.99）不成立；若两者在现有点上不可区分且外推一致，则本文结论在该数据集上被支持。</li></ol><p>这个实验的关键在于它把「幂律是否成立」和「幂律能否外推」拆开检验，后者才是配方的立身之本。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的反对不是质疑幂律，而是给它一个更廉价的替代解释：<strong>「环境多样性」的作用可能完全等价于视觉数据增强的强度</strong>。</p><p>理由链条来自论文自己的模型侧实验：冻结的 DINOv2 特征得 0.00 分，LoRA 得 0.72，全量微调得 0.90；ViT 从 S 到 L 单调变好；而动作头放大无效。这说明整条曲线上被数据推动的部件是<strong>视觉编码器的不变性</strong>，不是策略的行为多样性。如果真是这样，那么在单一环境采集的数据上施加足够强的背景替换、光照扰动、随机遮挡增强，应当能复现相当一部分「多环境」的收益。</p><p>因此反例实验是：固定 1 个环境 × 32 个物体的数据，加一组激进的合成背景替换增强（用 SAM 抠出前景、随机贴换背景），与真实的 32 环境数据在<strong>相同总演示数</strong>下对比留出环境的分数。若增强版能补回大部分差距，本文的坐标系就应该从「环境数」改写成「视觉不变性覆盖度」，32 这个数字也就失去了普适性——它只是当前编码器与当前增强流水线下的一个经验值。若增强版补不回来（例如在需要几何/深度线索的 Pour Water 上明显落后），则本文的「真实环境不可替代」立场得到强化。</p><p>另一类可预测的失效：任务难度由接触动力学而非感知主导时，环境多样性理应失效。Unplug Charger 的方差最大（±0.14）已是一个弱信号；把配方套到插孔、拧瓶盖这类高精度接触任务上，很可能看到曲线在低分区就走平。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：论文把「采多少个环境」当作标量预算问题，隐含假设所有环境是从同一分布里独立同分布抽出的、彼此可交换。但真实采集从来不是随机抽样——采集者会本能地找不一样的场景，而 32 这个阈值很可能对「采集者的选择策略」高度敏感。论文没有测量任何关于环境之间差异程度的量。</p><p><strong>(b) 可借鉴的相邻领域</strong>：把数据采集重新表述为<strong>最优实验设计 / coreset 选择</strong>问题。给定一个候选场景池的视觉表征（DINOv2 全局特征即可），选 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 个场景使得留出场景在该表征空间中的最坏情形距离最小——这正是 facility location 或 max-coverage 的形式，有成熟的贪心 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal">e</span></span></span></span> 保证。相应地，scaling law 的横轴应从「环境数量」换成「所选环境在表征空间中的覆盖半径」。</p><p><strong>(c) 第一个实验</strong>：在已采的 32 个环境上，用 DINOv2 特征分别做（i）随机选 8/16 个环境、（ii）贪心最大覆盖选 8/16 个环境，在相同演示总数下比较留出环境的分数。若贪心选法在 8 个环境时就追平随机选法的 16 个环境，那么「多样性」就获得了可计算的定义，采集预算可以在采之前而不是采之后决定；同时这也给出了一个可证伪的预测——覆盖半径相同的两组环境，无论数量多少，泛化分数应当相同。</p>',56)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
